 */
export function startBatch(): void {
  batchDepth++
}

/**
 * Run batched effects when all batches have ended
 * @internal
 */
export function endBatch(): void {
  if (batchDepth > 1) {
    batchDepth--
    return
  }

  batchDepth--
  let error: unknown
  while (batchBuffer.effect) {
    let e: ReactiveEffect | undefined = batchBuffer.effect
    batchBuffer.effect = undefined
